css:
.section_about-ms{position:relative}
.ab_ms_eyebrow{display:block;margin-bottom:28px}
.ab_ms_big{position:relative;z-index:3;max-width:22ch;font-weight:800;font-stretch:108%;font-size:clamp(30px,4.6vw,68px);line-height:1.04;letter-spacing:-0.02em;text-transform:uppercase;color:var(--_color---text--primary)}
.ab_ms_hl{color:var(--_color---brand--signal)}
.ab_ms_cols{position:relative;z-index:3;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-row-gap:clamp(24px,4vw,64px);grid-column-gap:clamp(24px,4vw,64px);max-width:1080px;margin-top:clamp(40px,5vw,64px)}
.ab_ms_text{font-size:clamp(17px,1.4vw,19px);line-height:1.65;color:var(--_color---text--secondary)}
.ab_ms_sign{position:relative;z-index:3;display:flex;flex-wrap:wrap;align-items:center;grid-row-gap:22px;grid-column-gap:22px;margin-top:34px}
.ab_ms_sign-text{color:var(--_color---text--tertiary);letter-spacing:0.1em;text-transform:uppercase}
.ab_promise_list{position:relative;z-index:3;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-row-gap:16px;grid-column-gap:16px;margin-top:clamp(48px,6vw,80px);margin-bottom:0;padding-left:0;list-style-type:none}
.ab_promise{position:relative;display:flex;flex-direction:column;grid-row-gap:10px;grid-column-gap:10px;padding-top:20px;padding-right:20px;padding-bottom:22px;padding-left:20px;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair);background-color:rgba(14,16,32,0.6)}
.ab_promise:hover{border-top-color:rgba(255,106,61,0.55);border-right-color:rgba(255,106,61,0.55);border-bottom-color:rgba(255,106,61,0.55);border-left-color:rgba(255,106,61,0.55);background-color:rgba(22,26,46,0.9)}
.ab_promise_n{display:flex;justify-content:space-between;align-items:center;font-size:11px;letter-spacing:0.12em;text-transform:uppercase;color:var(--_color---text--tertiary)}
.ab_promise_ck{display:grid;align-items:center;justify-items:center;width:18px;height:18px;border-top-width:1.5px;border-top-style:solid;border-top-color:var(--_color---neutral--hair-strong);border-right-width:1.5px;border-right-style:solid;border-right-color:var(--_color---neutral--hair-strong);border-bottom-width:1.5px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair-strong);border-left-width:1.5px;border-left-style:solid;border-left-color:var(--_color---neutral--hair-strong)}
.ab_promise_title{font-weight:800;font-stretch:112%;font-size:clamp(19px,1.5vw,22px);line-height:1.08;text-transform:uppercase;color:var(--_color---text--primary)}
.ab_promise_text{font-size:15px;line-height:1.5;color:var(--_color---text--secondary)}
@media screen and (max-width: 991px) {
.ab_promise_list{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media screen and (max-width: 767px) {
.ab_ms_cols{grid-template-columns:minmax(0,1fr)}
}
@media screen and (max-width: 479px) {
.ab_promise_list{grid-template-columns:minmax(0,1fr)}
}
